  KEY `payout_cycles_status_index` (`status`),
  KEY `payout_cycles_approval_status_index` (`approval_status`),
  KEY `payout_cycles_payment_status_index` (`payment_status`),
  KEY `payout_cycles_organization_id_index` (`organization_id`),
