DROP TABLE IF EXISTS `policy_daily_updates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `policy_daily_updates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint(20) unsigned DEFAULT NULL,
  `policy_id` bigint(20) unsigned NOT NULL,
  `update_date` date NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'pending',
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `policy_daily_update_unique` (`policy_id`,`update_date`),
  KEY `policy_daily_updates_updated_by_foreign` (`updated_by`),
  KEY `policy_daily_updates_update_date_index` (`update_date`),
  KEY `policy_daily_updates_status_index` (`status`),
  KEY `policy_daily_updates_organization_id_index` (`organization_id`),
  CONSTRAINT `policy_daily_updates_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `policy_daily_updates_policy_id_foreign` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`id`) ON DELETE CASCADE,
  CONSTRAINT `policy_daily_updates_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=191 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
