--
-- Table structure for table `policy_extraction_fields`
--

DROP TABLE IF EXISTS `policy_extraction_fields`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `policy_extraction_fields` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `extraction_session_id` bigint(20) unsigned NOT NULL,
  `field_category` enum('policy','customer','vehicle','premium','intermediary','additional','electric_vehicle') NOT NULL DEFAULT 'policy',
  `field_key` varchar(100) NOT NULL,
  `field_label` varchar(150) NOT NULL,
  `extracted_value` text DEFAULT NULL,
  `normalized_value` text DEFAULT NULL,
  `final_value` text DEFAULT NULL,
  `status` enum('confirmed','needs_review','missing','manual_entry','corrected') NOT NULL DEFAULT 'needs_review',
  `confidence` decimal(5,2) DEFAULT NULL,
  `validation_error` varchar(255) DEFAULT NULL,
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_session_field_key` (`extraction_session_id`,`field_key`),
  KEY `policy_extraction_fields_reviewed_by_foreign` (`reviewed_by`),
  KEY `policy_extraction_fields_field_category_index` (`field_category`),
  KEY `policy_extraction_fields_status_index` (`status`),
  CONSTRAINT `policy_extraction_fields_extraction_session_id_foreign` FOREIGN KEY (`extraction_session_id`) REFERENCES `policy_extraction_sessions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `policy_extraction_fields_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=500 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

