--
-- Table structure for table `policy_extraction_sessions`
--

DROP TABLE IF EXISTS `policy_extraction_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `policy_extraction_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` bigint(20) unsigned DEFAULT NULL,
  `document_id` bigint(20) unsigned DEFAULT NULL,
  `policy_id` bigint(20) unsigned DEFAULT NULL,
  `format_id` bigint(20) unsigned DEFAULT NULL,
  `file_path` varchar(255) NOT NULL,
  `original_filename` varchar(255) NOT NULL,
  `mime_type` varchar(100) NOT NULL DEFAULT 'application/pdf',
  `file_size` int(10) unsigned NOT NULL,
  `status` enum('uploaded','processing','review_required','confirmed','failed','cancelled') NOT NULL DEFAULT 'uploaded',
  `error_message` text DEFAULT NULL,
  `raw_text` mediumtext DEFAULT NULL,
  `confidence_score` decimal(5,2) DEFAULT NULL,
  `matched_customer_id` bigint(20) unsigned DEFAULT NULL,
  `matched_partner_id` bigint(20) unsigned DEFAULT NULL,
  `matched_broker_id` bigint(20) unsigned DEFAULT NULL,
  `matched_staff_id` bigint(20) unsigned DEFAULT NULL,
  `is_duplicate` tinyint(1) NOT NULL DEFAULT 0,
  `duplicate_policy_id` bigint(20) unsigned DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `policy_extraction_sessions_policy_id_foreign` (`policy_id`),
  KEY `policy_extraction_sessions_format_id_foreign` (`format_id`),
  KEY `policy_extraction_sessions_matched_customer_id_foreign` (`matched_customer_id`),
  KEY `policy_extraction_sessions_matched_partner_id_foreign` (`matched_partner_id`),
  KEY `policy_extraction_sessions_matched_staff_id_foreign` (`matched_staff_id`),
  KEY `policy_extraction_sessions_duplicate_policy_id_foreign` (`duplicate_policy_id`),
  KEY `policy_extraction_sessions_created_by_foreign` (`created_by`),
  KEY `policy_extraction_sessions_document_id_index` (`document_id`),
  KEY `policy_extraction_sessions_status_index` (`status`),
  KEY `policy_extraction_sessions_matched_broker_id_foreign` (`matched_broker_id`),
  KEY `policy_extraction_sessions_organization_id_index` (`organization_id`),
  CONSTRAINT `policy_extraction_sessions_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_duplicate_policy_id_foreign` FOREIGN KEY (`duplicate_policy_id`) REFERENCES `policies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_format_id_foreign` FOREIGN KEY (`format_id`) REFERENCES `document_formats` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_matched_broker_id_foreign` FOREIGN KEY (`matched_broker_id`) REFERENCES `partners` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_matched_customer_id_foreign` FOREIGN KEY (`matched_customer_id`) REFERENCES `customers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_matched_partner_id_foreign` FOREIGN KEY (`matched_partner_id`) REFERENCES `partners` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_matched_staff_id_foreign` FOREIGN KEY (`matched_staff_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `policy_extraction_sessions_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `policy_extraction_sessions_policy_id_foreign` FOREIGN KEY (`policy_id`) REFERENCES `policies` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

