  `display_name` varchar(150) NOT NULL,
  `category` varchar(50) NOT NULL,
  `language` varchar(15) NOT NULL DEFAULT 'en',
  `header_type` varchar(30) NOT NULL DEFAULT 'NONE',
  `header_text` text DEFAULT NULL,
  `body_text` text NOT NULL,
  `footer_text` text DEFAULT NULL,
  `buttons` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`buttons`)),
  `variables` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`variables`)),
  `variable_mappings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`variable_mappings`)),
  `status` varchar(30) NOT NULL DEFAULT 'draft',
  `meta_template_id` varchar(150) DEFAULT NULL,
  `meta_status` varchar(50) DEFAULT NULL,
  `meta_rejection_reason` text DEFAULT NULL,
  `meta_synced_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `whatsapp_templates_name_unique` (`name`),
  KEY `whatsapp_templates_created_by_foreign` (`created_by`),
  KEY `whatsapp_templates_updated_by_foreign` (`updated_by`),
  KEY `whatsapp_templates_category_index` (`category`),
  KEY `whatsapp_templates_language_index` (`language`),
  KEY `whatsapp_templates_status_index` (`status`),
  KEY `whatsapp_templates_meta_template_id_index` (`meta_template_id`),
  KEY `whatsapp_templates_meta_status_index` (`meta_status`),
  KEY `whatsapp_templates_organization_id_index` (`organization_id`),
  CONSTRAINT `whatsapp_templates_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `whatsapp_templates_organization_id_foreign` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `whatsapp_templates_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
